public class Project {
 public List<SystemRecord> Systems=new List<SystemRecord>();public List<Alliance> Alliances=new List<Alliance>();public string SourceHash="",SourceFile="",Owner="";
 public Alliance GetAlliance(string id){Alliance a=Alliances.Find(x=>x.ID==id);if(a==null){a=new Alliance{ID=id};Alliances.Add(a);}return a;}
 public void Merge(Project p){foreach(var a in p.Alliances){var old=Alliances.Find(x=>x.ID==a.ID);if(old==null)Alliances.Add(a);else{if(old.Name.Length==0)old.Name=a.Name;if(old.Icon.Length==0&&old.PreviewPng.Length==0)old.Icon=a.Icon;}} foreach(var r in p.Systems){var old=Systems.Find(x=>x.Key==r.Key);if(old==null)Systems.Add(r);else {if(old.Name.Length==0)old.Name=r.Name;if(old.Station.Length==0)old.Station=r.Station;if(old.Alliance.Length==0)old.Alliance=r.Alliance;old.Owned|=r.Owned;}}SourceFile=p.SourceFile;SourceHash=p.SourceHash;Owner=p.Owner;ImperialCore.Apply(this);}
}
public static class Data {
