 public static string ID(object o){object data=Get(o,"Data","8?J");object[] a=Arr(data??o);if(a.Length!=4)return "";uint[] words=a.Select(x=>Convert.ToUInt32(x)).ToArray();return words.All(x=>x==0)?"":string.Join("_",words.Select(x=>x.ToString()).ToArray());}
