 public static string Pack(object address){int gal=Num(Get(address,"RealityIndex","Iis"));object g=Get(address,"GalacticAddress","oZw");int x=Num(Get(g,"VoxelX","dZj")),y=Num(Get(g,"VoxelY","IyE")),z=Num(Get(g,"VoxelZ","uXE")),s=Num(Get(g,"SolarSystemIndex","vby"));if(gal<0||gal>255||x< -2047||x>2047||y< -127||y>127||z< -2047||z>2047||s<0||s>4095)throw new FormatException("UniverseAddress");ulong u=((ulong)s<<40)|((ulong)gal<<32)|((ulong)(y&255)<<24)|((ulong)(z&4095)<<12)|(uint)(x&4095);if(u==0)throw new FormatException("Empty address");return u.ToString("x16");}
