 public static byte[] ReadSave(string file){var info=new FileInfo(file);if(info.Length>128*1024*1024)throw new InvalidDataException("Save >128 MiB");byte[] b=File.ReadAllBytes(file);if(b.Length>0&&b[0]=='{')return b;using(var output=new MemoryStream()){int pos=0;while(pos<b.Length){if(pos+16>b.Length||BitConverter.ToUInt32(b,pos)!=0xfeeda1e5||BitConverter.ToUInt32(b,pos+12)!=0)throw new InvalidDataException("Save format");int c=checked((int)BitConverter.ToUInt32(b,pos+4)),n=checked((int)BitConverter.ToUInt32(b,pos+8));pos+=16;if(c<=0||c>b.Length-pos||output.Length+n>128*1024*1024)throw new InvalidDataException("Save bounds");byte[] block=new byte[c];Buffer.BlockCopy(b,pos,block,0,c);pos+=c;byte[] decoded=LZ4(block,n);output.Write(decoded,0,decoded.Length);}return output.ToArray();}}
 public static string Hash(string path){using(var s=File.OpenRead(path))using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(s)).Replace("-","").ToLowerInvariant();}
 public static Project Import(string file,string owner){byte[] b=ReadSave(file);object doc=Json().DeserializeObject(new UTF8Encoding(false,true).GetString(b).TrimEnd(new char[]{'\0'}));var p=new Project{SourceFile=Path.GetFileName(file),SourceHash=Hash(file)};object ctx=Get(doc,"BaseContext","vLc"),player=Get(ctx,"PlayerStateData","6f=");if(player==null)throw new InvalidDataException("BaseContext/PlayerStateData missing");object[] bases=Arr(Get(player,"PersistentPlayerBases","F?0"));var stations=bases.Where(x=>Str(Get(Get(x,"BaseType","peI"),"PersistentBaseTypes","DPp"))=="PlayerSpaceStationBase").ToArray();string[] owners=stations.Select(x=>Str(Get(Get(x,"Owner","3?K"),"UID","K7E"))).Where(x=>x.Length>0).Distinct().ToArray();if(owner.Length==0&&owners.Length==1)owner=owners[0];if(owner.Length==0&&owners.Length>1)throw new InvalidDataException("Multiple station owners: "+string.Join(", ",owners)+". Enter owner UID.");p.Owner=owner;
