 var systems=new Dictionary<string,SystemRecord>();foreach(object r in stations){object own=Get(r,"Owner","3?K");if(Str(Get(own,"UID","K7E"))!=owner||Str(Get(own,"PTK","D6b"))!="ST")continue;string u=UA(Get(r,"GalacticAddress","oZw"));SystemRecord s;if(!systems.TryGetValue(u,out s)){s=new SystemRecord{UA=u,Owned=true,Owner=owner,Evidence="owned_station",Selected=false};systems.Add(u,s);}s.Station=Repair(Str(Get(r,"Name","NKm")));}
 foreach(object r in Arr(Get(player,"TeleportEndpoints","nlG"))){if(Str(Get(r,"TeleporterType","iAF"))!="Spacestation")continue;string id=ID(Get(r,"AllianceId","6H2"));if(id.Length==0)continue;string u=Pack(Get(r,"UniverseAddress","yhJ"));SystemRecord s;if(!systems.TryGetValue(u,out s)){s=new SystemRecord{UA=u};systems.Add(u,s);}if(s.Alliance.Length>0&&s.Alliance!=id)throw new InvalidDataException("Conflicting cached alliance IDs: "+u);s.Alliance=id;s.Evidence="save_cached_allianceid";s.Selected=true;if(s.Station.Length==0)s.Station=Repair(Str(Get(r,"Name","NKm")));p.GetAlliance(id);}
 foreach(var s in systems.Values){string name;if(names.TryGetValue(s.UA,out name))s.Name=name;p.Systems.Add(s);}ImperialCore.Apply(p);return p;}
 public static string Hex(string text){byte[] b=Encoding.UTF8.GetBytes(text);if(b.Length>127){int n=127;while(n>0&&(b[n]&0xc0)==0x80)n--;Array.Resize(ref b,n);}return BitConverter.ToString(b).Replace("-","").ToLowerInvariant();}
 public static string Unhex(string h){if(h.Length%2!=0)throw new FormatException("UTF8 hex");byte[] b=new byte[h.Length/2];for(int i=0;i<b.Length;i++)b[i]=Convert.ToByte(h.Substring(i*2,2),16);return new UTF8Encoding(false,true).GetString(b);}
 public static string MigrateBundle(string baseDir){baseDir=Path.GetFullPath(baseDir).TrimEnd(new char[]{Path.DirectorySeparatorChar,Path.AltDirectorySeparatorChar});string dest=Path.Combine(baseDir,"IGM_datos"),old=Path.Combine(Directory.GetParent(Path.GetFullPath(baseDir)).FullName,"IGM_v031_datos");Directory.CreateDirectory(dest);string[][] pairs={new[]{"catalogo_observado.jsonl","catalogo_observado.jsonl"},new[]{"gestion_sistemas.tsv","gestion_sistemas.tsv"},new[]{"exploracion_v045.tsv","exploracion.tsv"},new[]{"colores_alianzas.tsv","colores_alianzas.tsv"},new[]{"ajustes_v045.ini","ajustes.ini"},new[]{"captura_v050.ini","captura.ini"}};foreach(var pair in pairs)CopyMissing(Path.Combine(old,pair[0]),Path.Combine(dest,pair[1]));CopyMissing(Path.Combine(Directory.GetParent(Path.GetFullPath(baseDir)).FullName,"IGM_v031.ini"),Path.Combine(dest,"IGM.ini"));foreach(var pair in new[]{new[]{"capturas_prueba_v050","capturas","*.bmp"},new[]{"iconos_alianzas","iconos_alianzas","*.igmicon"}}){string src=Path.Combine(old,pair[0]),target=Path.Combine(dest,pair[1]);Directory.CreateDirectory(target);if(Directory.Exists(src))foreach(string f in Directory.GetFiles(src,pair[2]))CopyMissing(f,Path.Combine(target,Path.GetFileName(f)));}return dest;}
 static void CopyMissing(string src,string dst){if(File.Exists(src)&&!File.Exists(dst)){try{File.Copy(src,dst,false);}catch(IOException){if(!File.Exists(dst))throw;}}}
 public static Project LoadMod(string dir){Project p=new Project();string f=Path.Combine(dir,"catalogo_observado.jsonl");if(File.Exists(f)){foreach(string line in File.ReadLines(f)){if(line.Trim().Length==0)continue;object r=Json().DeserializeObject(line);string u=UA("0x"+Str(Get(r,"system_ua"))),id=ID(Get(r,"alliance_id_words"));if(id.Length==0)continue;var s=p.Systems.Find(x=>x.UA==u);if(s==null){s=new SystemRecord{UA=u,Evidence="existing_mod"};p.Systems.Add(s);}s.Alliance=id;var a=p.GetAlliance(id);string n=Str(Get(r,"cached_alliance_name"));if(n.Length>0)a.Name=n;}}
 f=Path.Combine(dir,"exploracion.tsv");if(File.Exists(f))foreach(string line in File.ReadLines(f)){if(line.StartsWith("#")||line.Length==0)continue;var x=line.Split('\t');if(x.Length!=5)throw new InvalidDataException("exploracion.tsv");int planet=int.Parse(x[1]),pirate=int.Parse(x[2]),priority=int.Parse(x[3]);if(planet<0||planet>15||pirate< -1||pirate>1||priority<0||priority>3||x[4].Length>254)throw new InvalidDataException("exploracion.tsv bounds");Unhex(x[4]);if(planet!=0)continue;string u=UA("0x"+x[0]);var s=p.Systems.Find(z=>z.UA==u);if(s!=null)s.Name=Unhex(x[4]);}
 foreach(var a in p.Alliances){if(ImperialCore.IsAlliance(a.ID))continue;string icon=Path.Combine(dir,"iconos_alianzas",a.ID+".igmicon");if(File.Exists(icon)){IconCodec.Validate(File.ReadAllText(icon));a.Icon=File.ReadAllText(icon);}a.Initials=Initials(a.Name);}ImperialCore.Apply(p);return p;}
 public static string Initials(string n){if(n=="Imperio Español")return "IESP";return new string(n.Split(new[]{' ','-','_'},StringSplitOptions.RemoveEmptyEntries).Select(x=>char.ToUpperInvariant(x[0])).Where(char.IsLetter).Take(6).ToArray());}
 public static void SaveProject(Project p,string f){File.WriteAllText(f,Json().Serialize(p),new UTF8Encoding(false));}
 public static Project OpenProject(string f){Project p=Json().Deserialize<Project>(File.ReadAllText(f));if(p==null||p.Systems.Count>8192||p.Alliances.Count>4096||p.Systems.GroupBy(z=>z.Key).Any(z=>z.Count()>1))throw new InvalidDataException("Project");foreach(var a in p.Alliances){Words(a.ID);if(a.Icon.Length>0)IconCodec.Validate(a.Icon);}foreach(var s in p.Systems){UA("0x"+s.UA);if(s.Alliance.Length>0)Words(s.Alliance);}ImperialCore.Apply(p);return p;}
 public static string Export(Project project,string folder,bool checkGame){ImperialCore.Apply(project);if(checkGame&&Process.GetProcessesByName("NMS").Length>0)throw new InvalidOperationException("NMS is running. Close it before exporting.");folder=Path.GetFullPath(folder);if(!Directory.Exists(folder)||Path.GetFileName(folder)!="IGM_datos")throw new InvalidOperationException("Select IGM_datos");Project existing=LoadMod(folder);var known=existing.Systems.ToDictionary(x=>x.UA);var additions=new List<string>();var names=new List<string>();int conflicts=0;foreach(var s in project.Systems.Where(x=>x.Selected&&x.Alliance.Length>0&&!ImperialCore.Locked(x))){UA("0x"+s.UA);Words(s.Alliance);SystemRecord old;bool has=known.TryGetValue(s.UA,out old);if(has&&old.Alliance!=s.Alliance){conflicts++;continue;}Alliance a=project.GetAlliance(s.Alliance);if(!has||(a.NameEdited&&existing.Alliances.Any(z=>z.ID==a.ID&&z.Name!=a.Name))){var row=new Dictionary<string,object>{{"system_ua",s.UA},{"alliance_id_words",Words(s.Alliance)},{"cached_alliance_name",a.Name},{"source","save_cached_allianceid"},{"freshness","cached_not_server_verified"},{"source_sha256",project.SourceHash}};string line=Json().Serialize(row);if(Encoding.UTF8.GetByteCount(line)>1800)throw new InvalidDataException("Name too long");additions.Add(line);if(!has)known.Add(s.UA,s);}
 if(s.Name.Length>0&&(!has||old.Name.Length==0))names.Add(s.UA+"\t0\t-1\t1\t"+Hex(s.Name));}
 if(known.Count>4096)throw new InvalidDataException("Catalogue capacity 4096");var iconIds=new HashSet<string>(Directory.Exists(Path.Combine(folder,"iconos_alianzas"))?Directory.GetFiles(Path.Combine(folder,"iconos_alianzas"),"*.igmicon").Select(Path.GetFileNameWithoutExtension):new string[0]);foreach(var a in project.Alliances.Where(x=>x.Icon.Length>0&&!ImperialCore.IsAlliance(x.ID)))iconIds.Add(a.ID);if(iconIds.Count>128)throw new InvalidDataException("Icon capacity 128");var writes=new Dictionary<string,byte[]>();if(additions.Count>0)writes["catalogo_observado.jsonl"]=Append(folder,"catalogo_observado.jsonl",additions);if(names.Count>0)writes["exploracion.tsv"]=Append(folder,"exploracion.tsv",names);
 foreach(var a in project.Alliances.Where(x=>!ImperialCore.IsAlliance(x.ID))){if(a.PreviewPng.Length>0){using(var stream=new MemoryStream(Convert.FromBase64String(a.PreviewPng)))using(var bitmap=new Bitmap(stream))a.Icon=IconCodec.Encode(bitmap,false);}else if(a.Icon.Length==0&&a.ColorRGB!=0&&!File.Exists(Path.Combine(folder,"iconos_alianzas",a.ID+".igmicon"))){using(var bitmap=new Bitmap(192,192))using(var g=Graphics.FromImage(bitmap)){g.Clear(Color.Transparent);using(var brush=new SolidBrush(Color.FromArgb(a.ColorRGB)))g.FillPolygon(brush,new[]{new Point(96,2),new Point(190,96),new Point(96,190),new Point(2,96)});a.Icon=IconCodec.Encode(bitmap,true);}}}
 foreach(var a in project.Alliances.Where(x=>x.Icon.Length>0&&!ImperialCore.IsAlliance(x.ID))){Words(a.ID);IconCodec.Validate(a.Icon);string rel=Path.Combine("iconos_alianzas",a.ID+".igmicon"),path=Path.Combine(folder,rel);if(!File.Exists(path)||File.ReadAllText(path)!=a.Icon)writes[rel]=Encoding.ASCII.GetBytes(a.Icon);}
 foreach(var a in project.Alliances.Where(x=>!ImperialCore.IsAlliance(x.ID)&&(x.Icon.Length>0||x.PreviewPng.Length>0))){Words(a.ID);byte[] icon=IconCodec.ExportTexture(a);string rel=Path.Combine("iconos_alianzas",a.ID+".bmp"),path=Path.Combine(folder,rel);if(!File.Exists(path)||!File.ReadAllBytes(path).SequenceEqual(icon))writes[rel]=icon;}
 if(writes.Count==0)return "0 / conflicts: "+conflicts;
 string backup=Path.Combine(folder,"copias_companion",DateTime.UtcNow.ToString("yyyyMMdd_HHmmss_fff")+"_"+Guid.NewGuid().ToString("N").Substring(0,6));Directory.CreateDirectory(backup);var done=new List<string>();try{foreach(var w in writes){string dst=Path.Combine(folder,w.Key);if(File.Exists(dst)){string bak=Path.Combine(backup,w.Key);Directory.CreateDirectory(Path.GetDirectoryName(bak));File.Copy(dst,bak);}string tmp=dst+".companion.tmp";Directory.CreateDirectory(Path.GetDirectoryName(dst));File.WriteAllBytes(tmp,w.Value);}
 foreach(var w in writes){string dst=Path.Combine(folder,w.Key),tmp=dst+".companion.tmp";if(File.Exists(dst))File.Replace(tmp,dst,null);else File.Move(tmp,dst);done.Add(w.Key);}}
 catch{foreach(string rel in done){string dst=Path.Combine(folder,rel),bak=Path.Combine(backup,rel);if(File.Exists(bak))File.Copy(bak,dst,true);else File.Delete(dst);}throw;}finally{foreach(string rel in writes.Keys){string tmp=Path.Combine(folder,rel)+".companion.tmp";if(File.Exists(tmp))File.Delete(tmp);}}
 File.WriteAllText(Path.Combine(backup,"export.json"),Json().Serialize(new {records=additions.Count,names=names.Count,conflicts=conflicts,files=writes.Keys.ToArray(),utc=DateTime.UtcNow.ToString("o")}),new UTF8Encoding(false));return additions.Count+" / names: "+names.Count+" / icons: "+writes.Keys.Count(x=>x.EndsWith(".bmp"))+" / conflicts: "+conflicts;}
 static byte[] Append(string folder,string file,IEnumerable<string> lines){string path=Path.Combine(folder,file),old=File.Exists(path)?new UTF8Encoding(false,true).GetString(File.ReadAllBytes(path)):"";return new UTF8Encoding(false).GetBytes(old+(old.Length>0&&!old.EndsWith("\n")?"\r\n":"")+string.Join("\r\n",lines.ToArray())+"\r\n");}
}
public static class IconCodec {
 public static byte[] ExportTexture(Alliance a){using(var source=a.PreviewPng.Length>0?new Bitmap(new MemoryStream(Convert.FromBase64String(a.PreviewPng))):Decode(a.Icon,180))using(var target=new Bitmap(180,180,PixelFormat.Format32bppArgb)){using(var g=Graphics.FromImage(target)){g.Clear(Color.Transparent);g.InterpolationMode=InterpolationMode.HighQualityBicubic;g.CompositingMode=CompositingMode.SourceCopy;g.DrawImage(source,new Rectangle(0,0,180,180));}using(var stream=new MemoryStream())using(var b=new BinaryWriter(stream)){b.Write((byte)'B');b.Write((byte)'M');b.Write(54+180*180*4);b.Write(0);b.Write(54);b.Write(40);b.Write(180);b.Write(-180);b.Write((short)1);b.Write((short)32);b.Write(0);b.Write(180*180*4);b.Write(0);b.Write(0);b.Write(0);b.Write(0);for(int y=0;y<180;y++)for(int x=0;x<180;x++){Color c=target.GetPixel(x,y);b.Write(c.B);b.Write(c.G);b.Write(c.R);b.Write(c.A);}return stream.ToArray();}}}
 public const int Size=96;
 public static string Encode(Bitmap source,bool diamond){using(var small=new Bitmap(Size,Size,PixelFormat.Format32bppArgb)){using(var g=Graphics.FromImage(small)){g.Clear(Color.Transparent);g.InterpolationMode=InterpolationMode.HighQualityBicubic;float scale=Math.Min((float)Size/source.Width,(float)Size/source.Height);float w=source.Width*scale,h=source.Height*scale;g.DrawImage(source,(Size-w)/2,(Size-h)/2,w,h);}var pixels=new uint[Size*Size];var histogram=new Dictionary<uint,int>();for(int y=0;y<Size;y++)for(int x=0;x<Size;x++){uint c=Pixel(small,x,y,diamond);pixels[y*Size+x]=c;if(c!=0){uint rgb=c>>8;int value;histogram.TryGetValue(rgb,out value);histogram[rgb]=value+1;}}var palette=histogram.OrderByDescending(x=>x.Value).ThenBy(x=>x.Key).Take(16).Select(x=>x.Key).ToArray();for(int i=0;i<pixels.Length;i++){uint c=pixels[i];if(c==0)continue;uint rgb=c>>8,best=palette[0];long distance=long.MaxValue;foreach(uint q in palette){long dr=(long)(rgb>>16)-(long)(q>>16),dg=(long)((rgb>>8)&255)-(long)((q>>8)&255),db=(long)(rgb&255)-(long)(q&255),d=dr*dr+dg*dg+db*db;if(d<distance){distance=d;best=q;}}pixels[i]=(best<<8)|(c&255);}var runs=new List<string>();for(int y=0;y<Size;y++){int x=0;while(x<Size){uint c=pixels[y*Size+x];if(c==0){x++;continue;}int start=x++;while(x<Size&&pixels[y*Size+x]==c)x++;runs.Add(start+" "+y+" "+(x-start)+" "+c.ToString("x8"));}}return "IGMICON2 "+runs.Count+" 96"+"\n"+string.Join("\n",runs.ToArray())+"\n";}}
 static uint Pixel(Bitmap b,int x,int y,bool diamond){if(diamond&&Math.Abs(x-(Size-1)/2.0)+Math.Abs(y-(Size-1)/2.0)>Size/2.0-.2)return 0;Color c=b.GetPixel(x,y);int a=(int)Math.Round(c.A/85.0)*85;if(a==0)return 0;int r=(int)Math.Round(c.R/17.0)*17,g=(int)Math.Round(c.G/17.0)*17,bl=(int)Math.Round(c.B/17.0)*17;return (uint)(r<<24|g<<16|bl<<8|a);}
 public static void Validate(string text){string[] rows=text.Trim().Split('\n');string[] h=rows[0].Trim().Split(' ');int count;int dim=h.Length==3&&h[0]=="IGMICON2"&&h[2]=="96"?96:h.Length==2&&h[0]=="IGMICON1"?24:0;if(dim==0||!int.TryParse(h[1],out count)||count<0||count>dim*dim||rows.Length!=count+1)throw new InvalidDataException("Icon header");for(int i=1;i<rows.Length;i++){string[] p=rows[i].Trim().Split(' ');int x,y,n;uint c;if(p.Length!=4||!int.TryParse(p[0],out x)||!int.TryParse(p[1],out y)||!int.TryParse(p[2],out n)||!uint.TryParse(p[3],System.Globalization.NumberStyles.HexNumber,null,out c)||x<0||x>=dim||y<0||y>=dim||n<1||x+n>dim)throw new InvalidDataException("Icon run");}}
 public static Bitmap Decode(string text,int size){Validate(text);float dim=text.StartsWith("IGMICON2 ")?96f:24f;Bitmap b=new Bitmap(size,size);using(var g=Graphics.FromImage(b)){foreach(string row in text.Trim().Split('\n').Skip(1)){string[] p=row.Trim().Split(' ');uint c=Convert.ToUInt32(p[3],16);using(var brush=new SolidBrush(Color.FromArgb((int)(c&255),(int)(c>>24),(int)((c>>16)&255),(int)((c>>8)&255))))g.FillRectangle(brush,int.Parse(p[0])*size/dim,int.Parse(p[1])*size/dim,int.Parse(p[2])*size/dim,size/dim+.01f);}}return b;}
}
